/**
 * Lemmatize and normalize word to root form
 */
export function normalizeWord(rawWord: string): string {
  if (!rawWord) return '';
  let word = rawWord.toLowerCase().trim().replace(/^[^a-z0-9]+|[^a-z0-9]+$/gi, '');
  if (!word) return '';

  // 1. Irregular table match (e.g. went -> go, better -> good, children -> child)
  if (IRREGULAR_LEMMAS[word]) return IRREGULAR_LEMMAS[word];

  // 2. Direct dictionary match
  if (COMMON_DICT_DATA[word]) return word;

  // 3. Morphological regular suffix rules
  if (word.endsWith('ies') && word.length > 4) {
    const root = word.slice(0, -3) + 'y';
    if (COMMON_DICT_DATA[root]) return root;
    return root;
  }
  if (word.endsWith('ier') && word.length > 4) {
    const root = word.slice(0, -3) + 'y';
    if (COMMON_DICT_DATA[root]) return root;
  }
  if (word.endsWith('iest') && word.length > 5) {
    const root = word.slice(0, -4) + 'y';
    if (COMMON_DICT_DATA[root]) return root;
  }
  if (word.endsWith('ves') && word.length > 4) {
    const root = word.slice(0, -3) + 'f';
    if (COMMON_DICT_DATA[root]) return root;
  }
  if (word.endsWith('es') && word.length > 3) {
    const root = word.slice(0, -2);
    if (COMMON_DICT_DATA[root]) return root;
  }
  if (word.endsWith('s') && !word.endsWith('ss') && word.length > 3) {
    const root = word.slice(0, -1);
    if (COMMON_DICT_DATA[root]) return root;
  }
  if (word.endsWith('ing') && word.length > 4) {
    const base = word.slice(0, -3);
    if (COMMON_DICT_DATA[base]) return base;
    if (COMMON_DICT_DATA[base + 'e']) return base + 'e';
  }
  if (word.endsWith('ed') && word.length > 4) {
    const base = word.slice(0, -2);
    if (COMMON_DICT_DATA[base]) return base;
    if (COMMON_DICT_DATA[base + 'e']) return base + 'e';
  }
  if (word.endsWith('ly') && word.length > 4) {
    const base = word.slice(0, -2);
    if (COMMON_DICT_DATA[base]) return base;
  }

  return word;
}

import { lookupLocalDict as lookupCoreDict, normalizeWord as normalizeCoreWord } from './ecdictCore';

/**
 * Instant local lookup with 42,000+ ECDICT Core words and 94,000+ lemma fallbacks
 */
export function lookupLocalDict(rawWord: string): DictEntry {
  const norm = normalizeWord(rawWord);
  const direct = rawWord.toLowerCase().trim();
  if (COMMON_DICT_DATA[norm]) {
    const entry = COMMON_DICT_DATA[norm];
    return norm !== direct ? { ...entry, lemma: norm } : entry;
  }
  if (COMMON_DICT_DATA[direct]) {
    return COMMON_DICT_DATA[direct];
  }

  // Delegate to expanded 42,000+ ECDICT Core dictionary
  const coreEntry = lookupCoreDict(rawWord);
  if (coreEntry && !coreEntry.trans.startsWith('暂无离线释义')) {
    return coreEntry;
  }

  const rootHint = norm && norm !== direct ? ` (词根: ${norm})` : '';
  return {
    word: rawWord,
    phonetic: `/${rawWord.toLowerCase()}/`,
    pos: "word",
    trans: `暂无离线释义${rootHint}`,
    lemma: norm !== direct ? norm : undefined,
    cefr: "B1",
    collins: 1
  };
}
